package de.corporate.lc.lc.api;import de.corporate.lc.audit.service.AuditService;import de.corporate.lc.check.service.DocumentCheckService;import de.corporate.lc.lc.domain.Amendment;import de.corporate.lc.lc.service.AmendmentService;import org.springframework.http.MediaType;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class AmendmentController{private final AmendmentService service;private final DocumentCheckService checks;private final AuditService audit;public AmendmentController(AmendmentService s,DocumentCheckService c,AuditService a){service=s;checks=c;audit=a;}@PostMapping(value="/lcs/import/mt707",consumes=MediaType.TEXT_PLAIN_VALUE)public Amendment importMt707(@RequestBody String raw,Authentication auth){Amendment amendment=service.importMt707(raw);UUID id=amendment.getLetterOfCredit().getId();long reset=checks.invalidateDecisions(id);audit.record(auth,"MT707_IMPORTED","LETTER_OF_CREDIT",id,"Amendment "+amendment.getAmendmentNumber());if(reset>0)audit.record(auth,"DOCUMENT_CHECK_DECISIONS_RESET","LETTER_OF_CREDIT",id,reset+" Entscheidungen wegen MT707-Amendment zurückgesetzt");return amendment;}@GetMapping("/lcs/{id}/amendments")public List<Amendment> amendments(@PathVariable UUID id){return service.forLc(id);}}
